import{_ as a,o as n,a as p,b as e}from"./app.C41L12d5.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"跨代迁移兼容性指南","link":"/guide/cross_gen_migration_guide/overview"},{"text":"概述","link":"/guide/cross_gen_migration_guide/overview"}]},"headers":[],"relativePath":"guide/cross_gen_migration_guide/overview.md","filePath":"guide/cross_gen_migration_guide/overview.md","lastUpdated":1787050286000}'),l={name:"guide/cross_gen_migration_guide/overview.md"};function c(i,s,t,o,_,d){return n(),p("div",null,[...s[0]||(s[0]=[e(`<div><article class="markdown-body"><h1>概述<span id="ZH-CN_TOPIC_0000002535192325"></span></h1><p>Ascend C的核心设计目标之一是实现跨代兼容。然而，每一代芯片在微架构上都存在独特的硬件特性，因此无法保证所有接口仅通过重编译就能达成完全的跨代兼容。基于这一前提，本手册旨在为Ascend C算子开发者提供系统化指导，帮助将算子核函数（Kernel）代码从当前芯片平滑移植到目标代际芯片上运行，实现高效、可控的迁移。</p><p>如<a href="../programming_guide/language_extension/simd_builtin_keywords.html">SIMD-BuiltIn关键字</a>中所述，__NPU_ARCH__是Device侧AI Core代码中的一个预处理宏，用于标识AI处理器的架构版本。<span data-filter="950,A3,910b">例如，Ascend 950PR/Ascend 950DT的__NPU_ARCH__为3510，而Atlas A2 训练系列产品/Atlas A2 推理系列产品和Atlas A3 训练系列产品/Atlas A3 推理系列产品的__NPU_ARCH__则为2201。</span>因此，后续章节将以__NPU_ARCH__为主线，重点介绍相邻代际芯片间的平滑迁移方法。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>为保证兼容性，建议开发者在开发过程中尽量避免使用以下接口或编程方式，否则需自行保证兼容性：</p><ul><li>非Ascend C公开接口、结构体，例如<code>impl</code>目录下的接口、结构体等；</li><li>对芯片规格进行硬编码，例如： <div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">MAX_UB_SIZE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="p">;</span><span class="w">  </span>
<span class="n">ascendcPlatform</span><span class="p">.</span><span class="n">GetCoreMemSize</span><span class="p">(</span><span class="n">platform_ascendc</span><span class="o">::</span><span class="n">CoreMemType</span><span class="o">::</span><span class="n">UB</span><span class="p">,</span><span class="w"> </span><span class="n">MAX_UB_SIZE</span><span class="p">);</span>
<span class="p">...</span>
</code></pre></div></li><li>编译器内置API（BuiltIn API），例如： <div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">copy_gm_to_ubuf</span><span class="p">(</span><span class="n">input_1_local_UB</span><span class="p">,</span><span class="w"> </span><span class="n">input_1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">);</span>
</code></pre></div></li></ul></div><p>建议开发者采用以下实践：</p><ul><li>使用兼容的API接口。</li><li>若涉及特定领域的扩展特性，应在Device侧通过 <a href="../programming_guide/language_extension/simd_builtin_keywords.html"><code>__NPU_ARCH__</code>编译宏</a>进行隔离，在Host侧通过<code>SocVersion</code>进行隔离。</li><li>使用<code>&lt;&lt;&lt;&gt;&gt;&gt;</code>直调或 <a href="../programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/multi_branch_strategy.html">Tiling模板编程</a>。</li></ul><div data-filter="x90,9030"><blockquote><p>💡 请参考<a href="https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/cannkit-ascend-kirin-compatibility">昇腾到麒麟迁移指南</a>，了解如何将昇腾平台上开发的算子迁移到麒麟平台。</p></blockquote></div></article></div>`,1)])])}const h=a(l,[["render",c]]);export{g as __pageData,h as default};
